function replaceSource(action){
  if(!W.source)return action();
  confirmBox(tx('یک محتوا در حال پخش است. آیا مطمئنید می‌خواهید از پخش فعلی خارج شوید و محتوای جدید را جایگزین کنید؟','A title is currently playing. Are you sure you want to leave it and replace it with the new content?'),action);
}
