function toggleVoice(s){var st=document.getElementById('fnwp-voice-status'+(s||''));if(W.recorder){W.recorder.stop();return}if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia){alert(tx('مرورگر شما ضبط صدا را پشتیبانی نمی‌کند.','Voice recording is not supported by this browser.'));return}navigator.mediaDevices.getUserMedia({audio:true}).then(function(stream){var chunks=[],rec=new MediaRecorder(stream);W.recorder=rec;if(st)st.textContent=tx('در حال ضبط… دوباره بزنید برای ارسال','Recording… tap again to send');rec.ondataavailable=function(x){if(x.data.size)chunks.push(x.data)};rec.onstop=function(){stream.getTracks().forEach(function(t){t.stop()});W.recorder=null;var blob=new Blob(chunks,{type:rec.mimeType||'audio/webm'});if(blob.size>4*1024*1024){alert(tx('ویس خیلی بزرگ است.','Voice message is too large.'));return}var rd=new FileReader();rd.onload=function(){var p=profile();pushChat({kind:'chat',name:p.name,avatar:p.avatar,isOwner:W.owner,media:rd.result,mediaType:'audio',fileName:'voice.webm',uid:W.uid,at:Date.now()});if(st)st.textContent=''};rd.readAsDataURL(blob)};rec.start()}).catch(function(){if(st)st.textContent='';alert(tx('دسترسی میکروفون داده نشد.','Microphone permission was denied.'))})}
