function jumpTo(id){var x=document.getElementById('fnwp-msg-'+id);if(x){x.scrollIntoView({behavior:'smooth',block:'center'});x.classList.add('fnwp-pinned');setTimeout(function(){x.classList.remove('fnwp-pinned')},1600)}}
function members(){var on=document.getElementById('fnwp-online'),pr=(W.lastPresence||{}),list=Object.keys(pr).filter(function(k){return Date.now()-(pr[k]&&pr[k].at||0)<100000}).map(function(k){var x=pr[k]||{};return '<div class="fnwp-member">'+(x.avatar?'<img class="fnwp-avatar" src="'+esc(x.avatar)+'" alt="">':'<span class="fnwp-avatar">'+initials(x.name)+'</span>')+'<span>'+esc(x.name||'Guest')+(k===W.uid?' <small>(you)</small>':'')+(x.isOwner?'<span class="fnwp-verified-label"><i class="fa-solid fa-circle-check"></i> creator</span>':'')+'</span></div>'}).join('');modal('<button class="fnwp-x" onclick="FNWatchParty.room()">×</button><h2 class="fnwp-title">'+tx('اعضای آنلاین','Online members')+'</h2><div class="fnwp-members">'+(list||'<p class="fnwp-note">'+tx('عضوی آنلاین نیست.','No one is online.')+'</p>')+'</div><button class="fnwp-btn" style="margin-top:14px;width:100%" onclick="FNWatchParty.room()">'+tx('بازگشت','Back')+'</button>')}
function confirmBox(text,yes){modal('<div class="fnwp-confirm"><h2 class="fnwp-title">'+tx('تأیید','Confirm')+'</h2><p class="fnwp-sub">'+text+'</p><div class="fnwp-actions"><button class="fnwp-btn primary" onclick="FNWatchParty.confirmYes()">'+tx('بله','Yes')+'</button><button class="fnwp-btn" onclick="FNWatchParty.room()">'+tx('خیر','No')+'</button></div></div>');W.confirmYes=yes}
function removeSaved(n){var x=rooms()[n];if(!x)return;if(x.owner)confirmBox(tx('آیا مطمئنید می‌خواهید این روم را برای همه حذف کنید؟ لینک و رمز هم دیگر کار نخواهند کرد.','Are you sure you want to delete this room for everyone? Its link and password will stop working.'),async function(){try{await boot();var ref=W.F.ref(W.db,'watchPartyRooms/'+n),s=await W.F.get(ref);if(s.exists()&&s.val().owner===W.uid)await W.F.remove(ref);else throw tx('فقط سازنده می‌تواند روم را حذف کند.','Only the creator can delete the room.');dropRoom(n);hub()}catch(e){alert(err(e));hub()}});else confirmBox(tx('آیا مطمئنید می‌خواهید از این روم خارج شوید؟ بعداً می‌توانید با نام و رمز دوباره وارد شوید.','Are you sure you want to leave this room? You can join again later with its name and password.'),function(){dropRoom(n);hub()})}
function deleteRoom(){if(!W.owner)return;var n=W.room;confirmBox(tx('آیا مطمئنید می‌خواهید این روم را برای همه حذف کنید؟ این کار برگشت ندارد.','Are you sure you want to delete this room for everyone? This cannot be undone.'),async function(){try{var s=await W.F.get(W.roomRef);if(!s.exists()||s.val().owner!==W.uid)throw tx('فقط سازنده می‌تواند روم را حذف کند.','Only the creator can delete the room.');await W.F.remove(W.roomRef);dropRoom(n);close();hub()}catch(e){alert(err(e));roomView()}})}
function share(){var room=W.room||'',saved=rooms()[room]||{},pass=saved.password||'',u='https://alireza-spec.github.io/FN/?room='+encodeURIComponent(room)+'&password='+encodeURIComponent(pass)+'#room='+encodeURIComponent(room)+'&password='+encodeURIComponent(pass),who=profile().name||'Guest '+(W.uid?W.uid.slice(-5):'00000'),text='Hello dear friend, '+who+' invited you to their room in Family Night\n\nRoom\'s Name: '+room+'\nRoom\'s Password: '+pass+'\nRoom\'s Link: '+u+'\nvia Family Night (Watch Party)\n\nOpen the link to join instantly.';pushChat({kind:'invite',name:who,inviter:who,avatar:profile().avatar,isOwner:W.owner,room:room,password:pass,url:u,uid:W.uid,at:Date.now()});if(navigator.share)navigator.share({title:'Family Night — '+room,text:text}).catch(function(){});else if(navigator.clipboard)navigator.clipboard.writeText(text).then(function(){alert(tx('متن دعوت، نام روم، رمز و لینک کپی شد.','Invitation text, room name, password and link copied.'))})}
function copy(id){var e=document.getElementById(id);if(!e)return;navigator.clipboard&&navigator.clipboard.writeText(e.value).then(function(){var b=tx('کپی شد','Copied');e.setAttribute('aria-label',b)})}function eye(id){var e=document.getElementById(id);e.type=e.type==='password'?'text':'password'}
function exitRoom(){if(!W.joined){hub();return}confirmBox(tx('می‌خواهید از این روم خارج شوید؟ برای ورود دوباره، نام و رمز روم را لازم دارید.','Do you want to leave this room? You will need the room name and password to join again.'),function(){hub()})}
async function fullscreen(){var box=R.querySelector('.fnwp-box');W.fs=!W.fs;R.classList.toggle('fs-open',W.fs);if(box)box.classList.toggle('fnwp-fullscreen-shell',W.fs);if(W.fs){updateChatUnread();try{if(box&&box.requestFullscreen&&!document.fullscreenElement)await box.requestFullscreen({navigationUI:'hide'});if(screen.orientation&&screen.orientation.lock)await screen.orientation.lock('landscape')}catch(e){/* CSS fullscreen remains available where native fullscreen/orientation is blocked. */}}else{R.classList.remove('drawer-open');if(box)box.classList.remove('drawer-open');updateChatUnread();try{if(document.fullscreenElement)await document.exitFullscreen();if(screen.orientation&&screen.orientation.unlock)screen.orientation.unlock()}catch(e){}}}
function drawer(){var open=!R.classList.contains('drawer-open');R.classList.toggle('drawer-open',open);var b=R.querySelector('.fnwp-box');if(b)b.classList.toggle('drawer-open',open);if(open)markChatSeen();else updateChatUnread()}
function composerIsFocused(){var a=document.activeElement;return !!(a&&a.tagName==='TEXTAREA'&&/^fnwp-chat-input(?:drawer)?$/.test(a.id)&&R.classList.contains('drawer-open'))}
document.addEventListener('fullscreenchange',function(){if(!document.fullscreenElement&&W.fs){if(composerIsFocused())return;W.fs=false;R.classList.remove('fs-open','drawer-open');var b=R.querySelector('.fnwp-box');if(b)b.classList.remove('fnwp-fullscreen-shell','drawer-open');try{if(screen.orientation&&screen.orientation.unlock)screen.orientation.unlock()}catch(e){}}})
R.addEventListener('click',function(e){if(e.target===R)close()});window.addEventListener('beforeunload',function(){leave(true)});window.addEventListener('DOMContentLoaded',function(){try{var url=new URL(location.href),q=url.searchParams,n=q.get('room'),pw=q.get('password');if(!pw&&url.hash){var hp=new URLSearchParams(url.hash.replace(/^#/,'')).get('password');if(hp)pw=hp}if(!n&&url.hash)n=new URLSearchParams(url.hash.replace(/^#/,'')).get('room');if(n&&/^[A-Za-z0-9_-]{5,32}$/.test(n)){n=n.toUpperCase();if(!pw){try{pw=(rooms()[n]||{}).password||''}catch(e){}}if(pw){linkConfirm(n,pw)}else joinForm(n)}}catch(e){}});
async function linkConfirm(n,p){
  var ownerName=tx('سازنده روم','Room creator');
  try{await boot();var snap=await W.F.get(W.F.ref(W.db,'watchPartyRooms/'+n));if(!snap.exists()){joinForm(n);showError(tx('این روم وجود ندارد یا حذف شده است.','This room does not exist or was deleted.'));return}var v=snap.val()||{};ownerName=v.ownerName||ownerName;var ps=await W.F.get(W.F.ref(W.db,'watchPartyRooms/'+n+'/presence'));var people=ps.exists()?ps.val()||{}:{};Object.keys(people).some(function(k){if(people[k]&&people[k].isOwner){ownerName=people[k].name||ownerName;return true}return false});
  }catch(e){ownerName=tx('سازنده روم','Room creator')}
  modal('<div class="fnwp-link-confirm"><div style="font-size:42px;margin-bottom:8px;">🎬</div><h2 class="fnwp-title">'+tx('ورود به روم؟','Join this room?')+'</h2><p class="fnwp-sub">'+tx('آیا می‌خواهید وارد روم زیر شوید؟','Would you like to join the following room?')+'</p><div class="fnwp-confirm-room">'+esc(n)+'</div><p class="fnwp-sub" style="margin-top:8px">'+tx('ساخته‌شده توسط ','Created by ')+'<span class="fnwp-confirm-owner">'+esc(ownerName)+'</span></p><div class="fnwp-actions"><button class="fnwp-btn primary" id="fnwp-link-yes" onclick="FNWatchParty.confirmYes()">'+tx('تأیید و ورود','Confirm & Join')+'</button><button class="fnwp-btn" onclick="FNWatchParty.cancelLink()">'+tx('لغو','Cancel')+'</button></div></div>');
  W.confirmYes=function(){var f=W.confirmYes;W.confirmYes=null;var b=document.getElementById('fnwp-link-yes');if(b){b.disabled=true;b.innerHTML='<span class="fnwp-load"><i class="fnwp-spinner"></i>'+tx('در حال ورود…','Joining…')+'</span>'}joinWith(n,p,null).catch(function(e){linkConfirmError(e,n,p)})};
}
